css = '\n/* CFData v4.5: compact NSB UI + history */\n#nsbControls {\n    gap: 8px 10px !important;\n}\n#nsbControls .control-title {\n    margin: 0 0 2px !important;\n    font-size: 13px !important;\n}\n#nsbControls .option-item {\n    min-height: 40px !important;\n    padding: 7px 10px !important;\n    gap: 8px !important;\n    border-radius: 9px !important;\n    box-shadow: none !important;\n}\n#nsbControls .option-item .label {\n    width: 108px !important;\n    font-size: 12px !important;\n    line-height: 1.25 !important;\n}\n#nsbControls input,\n#nsbControls select {\n    min-height: 34px !important;\n    padding: 6px 9px !important;\n    border-radius: 8px !important;\n    font-size: 13px !important;\n    line-height: 18px !important;\n}\n#nsbControls .speed-url-select {\n    min-height: 34px !important;\n}\n#nsbControls .mini-action-btn {\n    width: 30px !important;\n    height: 30px !important;\n}\n#nsbControls .option-item.full-width {\n    padding-top: 8px !important;\n    padding-bottom: 8px !important;\n}\n#nsbManualInput {\n    width: 100% !important;\n    min-height: 92px !important;\n    resize: vertical !important;\n    background: var(--bg-color) !important;\n    color: var(--text-main) !important;\n    border: 1px solid var(--border-color) !important;\n    border-radius: 8px !important;\n    padding: 9px 10px !important;\n    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace !important;\n    font-size: 12px !important;\n    line-height: 1.55 !important;\n    outline: none !important;\n}\n#nsbManualInput:focus {\n    border-color: var(--primary-color) !important;\n    box-shadow: 0 0 0 2px rgba(59,130,246,.12) !important;\n}\n#nsbManualInput::placeholder { color: var(--text-secondary) !important; opacity: .78; }\n\n.v45-history-btn {\n    width: auto !important;\n    min-width: 52px !important;\n    padding: 0 9px !important;\n    gap: 5px !important;\n    font-size: 13px !important;\n    font-weight: 700 !important;\n    white-space: nowrap;\n    position: relative;\n}\n.v45-history-count {\n    min-width: 18px;\n    height: 18px;\n    padding: 0 5px;\n    border-radius: 999px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    background: var(--primary-color);\n    color: #fff;\n    font-size: 10px;\n    line-height: 1;\n}\n.v45-overlay {\n    position: fixed;\n    inset: 0;\n    z-index: 9998;\n    background: rgba(2,6,23,.68);\n    backdrop-filter: blur(3px);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n}\n.v45-overlay.hidden { display: none !important; }\n.v45-history-panel {\n    width: min(980px, 96vw);\n    max-height: 88vh;\n    overflow: hidden;\n    background: var(--card-bg);\n    color: var(--text-main);\n    border: 1px solid var(--border-color);\n    border-radius: 16px;\n    box-shadow: 0 24px 70px rgba(0,0,0,.35);\n    display: flex;\n    flex-direction: column;\n}\n.v45-history-head {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    padding: 14px 16px;\n    border-bottom: 1px solid var(--border-color);\n}\n.v45-history-head h3 { margin: 0; font-size: 16px; }\n.v45-history-actions { display:flex; gap:8px; }\n.v45-history-actions button {\n    border: 1px solid var(--border-color);\n    background: var(--bg-color);\n    color: var(--text-main);\n    border-radius: 8px;\n    padding: 7px 10px;\n    cursor: pointer;\n}\n.v45-history-body {\n    padding: 12px;\n    overflow: auto;\n}\n.v45-history-empty { color: var(--text-secondary); text-align:center; padding:40px 10px; }\n.v45-history-card {\n    border: 1px solid var(--border-color);\n    background: var(--bg-color);\n    border-radius: 10px;\n    padding: 10px 12px;\n    margin-bottom: 9px;\n}\n.v45-history-summary {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    flex-wrap: wrap;\n}\n.v45-history-title { font-weight: 800; font-size: 13px; }\n.v45-history-meta { color: var(--text-secondary); font-size: 12px; margin-top: 4px; }\n.v45-history-stats { display:flex; gap:6px; flex-wrap:wrap; }\n.v45-chip {\n    border: 1px solid var(--border-color);\n    border-radius: 999px;\n    padding: 3px 7px;\n    font-size: 11px;\n    color: var(--text-secondary);\n    background: var(--card-bg);\n}\n.v45-chip.good { color:#059669; border-color:rgba(16,185,129,.35); }\n.v45-history-card details { margin-top:8px; }\n.v45-history-card summary { cursor:pointer; color:var(--primary-color); font-size:12px; }\n.v45-history-table-wrap { overflow:auto; margin-top:8px; }\n.v45-history-table { width:100%; border-collapse:collapse; font-size:11px; white-space:nowrap; }\n.v45-history-table th,.v45-history-table td { padding:5px 7px; border-bottom:1px solid var(--border-color); text-align:left; }\n\n#scanTable th.v45-seq-cell,\n#scanTable td.v45-seq-cell {\n    width: 44px;\n    min-width: 44px;\n    max-width: 44px;\n    text-align: center !important;\n    color: var(--text-secondary);\n    font-variant-numeric: tabular-nums;\n}\n#scanTable th.v45-country-cell,\n#scanTable td.v45-country-cell {\n    min-width: 62px;\n    text-align: center !important;\n    font-weight: 700;\n}\n.ip-prefix-emphasis { color:#ef4444 !important; font-weight:900 !important; }\n.ip-host-emphasis { color:inherit !important; font-weight:600 !important; }\n\n@media (max-width: 768px) {\n    #nsbControls { grid-template-columns: 1fr !important; gap:7px !important; }\n    #nsbControls .option-item .label { width: 100px !important; }\n    .v45-history-panel { width: 98vw; max-height:92vh; }\n}\n'
js = '\n(() => {\n    \'use strict\';\n    if (window.__CFDATA_V45_INSTALLED__) return;\n    window.__CFDATA_V45_INSTALLED__ = true;\n\n    const HISTORY_KEY = \'cfdata-v45-history\';\n    const BEST_KEY = \'cfdata-v45-best-library\';\n    const SETTINGS_KEY = \'cfdata-v45-settings\';\n    const DEFAULT_SETTINGS = { bestSpeedThreshold: 50, historyLimit: 50, lossLimit: 100 };\n    let v45OriginalAutoUploadNSB = null;\n    let v45OriginalAutoUploadOfficial = null;\n    let v45DecorateQueued = false;\n    let v45LastBestSyncSignature = \'\';\n\n    function v45EscapeHTML(value) {\n        const text = String(value ?? \'\');\n        if (typeof escapeHTML === \'function\') return escapeHTML(text);\n        return text.replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\').replace(/"/g, \'&quot;\').replace(/\'/g, \'&#039;\');\n    }\n\n    function v45LoadSettings() {\n        try {\n            const parsed = JSON.parse(localStorage.getItem(SETTINGS_KEY) || \'{}\');\n            return { ...DEFAULT_SETTINGS, ...(parsed || {}) };\n        } catch (_) {\n            return { ...DEFAULT_SETTINGS };\n        }\n    }\n\n    function v45SaveSettings() {\n        const best = Math.max(0, parseFloat(document.getElementById(\'nsbBestSpeedThreshold\')?.value || \'50\') || 0);\n        const history = Math.min(500, Math.max(1, parseInt(document.getElementById(\'nsbHistoryLimit\')?.value || \'50\', 10) || 50));\n        const loss = Math.min(100, Math.max(0, parseFloat(document.getElementById(\'nsbLossLimit\')?.value || \'100\') || 0));\n        try { localStorage.setItem(SETTINGS_KEY, JSON.stringify({ bestSpeedThreshold: best, historyLimit: history, lossLimit: loss })); } catch (_) {}\n        try {\n            const current = v45LoadBest().filter(x => Number(x.speed) > best).sort(v45BestCompare).slice(0, history);\n            v45SaveBest(current);\n            v45UpdateHistoryBadge();\n            v45RenderHistory();\n        } catch (_) {}\n    }\n\n    function v45InstallCompactSettings() {\n        const settings = v45LoadSettings();\n        const speedLimit = document.getElementById(\'nsbSpeedLimit\');\n        const anchor = speedLimit?.closest(\'.option-item\');\n        if (anchor && !document.getElementById(\'nsbBestSpeedThreshold\')) {\n            const best = document.createElement(\'div\');\n            best.className = \'option-item\';\n            best.innerHTML = `<span class="label" title="测速完成后，只有速度严格超过此值的结果才有资格进入历史最优 Top N；配置 GitHub 后同步 best.txt">⭐ 入库速度</span><input id="nsbBestSpeedThreshold" type="number" min="0" step="0.1" value="${Number(settings.bestSpeedThreshold) || 50}" placeholder="默认 50 MB/s">`;\n            anchor.insertAdjacentElement(\'afterend\', best);\n\n            const history = document.createElement(\'div\');\n            history.className = \'option-item\';\n            history.innerHTML = `<span class="label" title="历史最优池最多保留多少个 IP；达到上限后，只有能进入当前 Top N 的新成绩才会挤掉末位">🏆 历史最优数量</span><input id="nsbHistoryLimit" type="number" min="1" max="500" value="${Number(settings.historyLimit) || 50}" placeholder="默认 50 个">`;\n            best.insertAdjacentElement(\'afterend\', history);\n        }\n\n        const delayInput = document.getElementById(\'nsbDelay\');\n        const delayAnchor = delayInput?.closest(\'.option-item\');\n        if (delayAnchor && !document.getElementById(\'nsbLossLimit\')) {\n            const loss = document.createElement(\'div\');\n            loss.className = \'option-item\';\n            loss.innerHTML = `<span class="label" title="允许的最大丢包率。超过该百分比的 IP 在扫描阶段直接淘汰，不显示、不占延迟合格数量，程序继续测试下一个。100 表示不限制；0 表示只接受 0% 丢包">📉 最大丢包率</span><input id="nsbLossLimit" type="number" min="0" max="100" step="1" value="${Number.isFinite(Number(settings.lossLimit)) ? Number(settings.lossLimit) : 100}" placeholder="0-100%">`;\n            delayAnchor.insertAdjacentElement(\'afterend\', loss);\n        }\n\n        [\'nsbBestSpeedThreshold\', \'nsbHistoryLimit\', \'nsbLossLimit\'].forEach(id => {\n            document.getElementById(id)?.addEventListener(\'change\', v45SaveSettings);\n        });\n    }\n\n    function v45NormalizeSourceToken(source) {\n        let s = String(source ?? \'\').trim();\n        if (!s) return \'\';\n        const bracket = s.match(/^\\[([^\\]]+)\\](?:\\s*:\\s*\\d+)?/);\n        if (bracket) return bracket[1];\n        s = s.split(/[\\s,，;；]+/)[0] || \'\';\n        if (/^\\d{1,3}(?:\\.\\d{1,3}){3}:\\d+$/.test(s)) s = s.replace(/:\\d+$/, \'\');\n        return s;\n    }\n\n    function v45SourceHighlight(ip, originalInput) {\n        const raw = String(ip ?? \'\').trim().replace(/^\\[|\\]$/g, \'\');\n        const source = v45NormalizeSourceToken(originalInput);\n        if (!raw) return v45EscapeHTML(raw);\n        if (!source) return v45EscapeHTML(raw);\n\n        const sourceNoCIDR = source.split(\'/\')[0].replace(/^\\[|\\]$/g, \'\');\n        if (!source.includes(\'/\') && sourceNoCIDR.toLowerCase() === raw.toLowerCase()) {\n            return `<span class="ip-prefix-emphasis">${v45EscapeHTML(raw)}</span>`;\n        }\n\n        const cidr = source.match(/\\/([0-9]{1,3})$/);\n        if (!cidr) return v45EscapeHTML(raw);\n        const bits = parseInt(cidr[1], 10);\n\n        if (raw.includes(\':\')) {\n            if (!(bits >= 0 && bits <= 128)) return v45EscapeHTML(raw);\n            const count = Math.ceil(bits / 16);\n            if (count <= 0) return v45EscapeHTML(raw);\n            const parts = raw.split(\':\');\n            if (parts.length < count) return v45EscapeHTML(raw);\n            const prefix = parts.slice(0, count).join(\':\');\n            const rest = raw.slice(prefix.length);\n            return `<span class="ip-prefix-emphasis">${v45EscapeHTML(prefix)}</span><span class="ip-host-emphasis">${v45EscapeHTML(rest)}</span>`;\n        }\n\n        if (!(bits >= 0 && bits <= 32)) return v45EscapeHTML(raw);\n        const count = Math.ceil(bits / 8);\n        if (count <= 0) return v45EscapeHTML(raw);\n        const parts = raw.split(\'.\');\n        if (parts.length !== 4) return v45EscapeHTML(raw);\n        const prefix = parts.slice(0, Math.min(4, count)).join(\'.\');\n        const rest = raw.slice(prefix.length);\n        return `<span class="ip-prefix-emphasis">${v45EscapeHTML(prefix)}</span><span class="ip-host-emphasis">${v45EscapeHTML(rest)}</span>`;\n    }\n\n    function v45InstallIPRendering() {\n        // 固定输出：IPv6 永远 [IPv6]:PORT，IPv4 永远 IPv4:PORT，不再提供易忘记的选择框。\n        document.getElementById(\'resultIPOutputFormat\')?.closest(\'.modal-field\')?.remove();\n        document.getElementById(\'copyIPOutputFormat\')?.closest(\'.modal-field\')?.remove();\n\n        if (typeof formatOutputIP === \'function\') {\n            formatOutputIP = function(ip) {\n                const raw = String(ip ?? \'\').trim().replace(/^\\[|\\]$/g, \'\');\n                if (raw.includes(\':\')) return `[${raw}]`;\n                return raw;\n            };\n        }\n        if (typeof getOutputIPFormat === \'function\') {\n            getOutputIPFormat = function() { return \'auto\'; };\n        }\n        if (typeof renderIPPrefixEmphasis === \'function\') {\n            renderIPPrefixEmphasis = function(ip, originalInput) { return v45SourceHighlight(ip, originalInput); };\n        }\n        if (typeof renderIPCell === \'function\') {\n            renderIPCell = function(ip, originalInput) {\n                const rawIP = String(ip ?? \'\').trim().replace(/^\\[|\\]$/g, \'\');\n                const displayIP = v45SourceHighlight(rawIP, originalInput);\n                const jsIP = typeof escapeJSString === \'function\' ? escapeJSString(rawIP) : rawIP.replace(/\'/g, "\\\\\'");\n                const hrefIP = encodeURIComponent(rawIP);\n                let domainIcon = \'\';\n                if (originalInput && originalInput !== rawIP) {\n                    const source = String(originalInput);\n                    const isDomain = /[a-zA-Z]/.test(source) && !source.includes(\'/\') && !source.includes(\':\');\n                    if (isDomain) domainIcon = `<span class="ip-detail-link" title="来源域名: ${v45EscapeHTML(source)}" onclick="event.stopPropagation()" style="cursor:default;">ⓗ</span>`;\n                }\n                return `<span class="ip-cell"><span class="copy-ip" title="${v45EscapeHTML(rawIP)}" onclick="copyToClipboard(\'${jsIP}\', event)">${displayIP}</span>${domainIcon}<a class="ip-detail-link" href="https://ippure.com/?ip=${hrefIP}" target="_blank" rel="noopener noreferrer" title="前往 ippure.com 查看 IP 详情" onclick="event.stopPropagation()">ⓘ</a></span>`;\n            };\n        }\n    }\n\n    const V45_DC_COUNTRY = {\n        NRT:\'JP\',HND:\'JP\',KIX:\'JP\',FUK:\'JP\',OKA:\'JP\',NGO:\'JP\',CTS:\'JP\',\n        HKG:\'HK\',TPE:\'TW\',KHH:\'TW\',SIN:\'SG\',ICN:\'KR\',GMP:\'KR\',PUS:\'KR\',\n        LAX:\'US\',SJC:\'US\',SFO:\'US\',SEA:\'US\',PDX:\'US\',PHX:\'US\',DEN:\'US\',DFW:\'US\',IAH:\'US\',\n        ORD:\'US\',MSP:\'US\',DTW:\'US\',ATL:\'US\',MIA:\'US\',TPA:\'US\',MCO:\'US\',CLT:\'US\',IAD:\'US\',\n        EWR:\'US\',JFK:\'US\',BOS:\'US\',SLC:\'US\',LAS:\'US\',SAN:\'US\',AUS:\'US\',BNA:\'US\',CMH:\'US\',\n        FRA:\'DE\',MUC:\'DE\',DUS:\'DE\',HAM:\'DE\',BER:\'DE\',LHR:\'GB\',MAN:\'GB\',EDI:\'GB\',CDG:\'FR\',MRS:\'FR\',\n        AMS:\'NL\',BRU:\'BE\',MAD:\'ES\',BCN:\'ES\',LIS:\'PT\',MXP:\'IT\',FCO:\'IT\',VIE:\'AT\',ZRH:\'CH\',GVA:\'CH\',\n        WAW:\'PL\',PRG:\'CZ\',BUD:\'HU\',ARN:\'SE\',OSL:\'NO\',CPH:\'DK\',HEL:\'FI\',DUB:\'IE\',\n        SYD:\'AU\',MEL:\'AU\',BNE:\'AU\',PER:\'AU\',AKL:\'NZ\',YVR:\'CA\',YYZ:\'CA\',YUL:\'CA\',\n        BOM:\'IN\',DEL:\'IN\',MAA:\'IN\',BLR:\'IN\',HYD:\'IN\',CCU:\'IN\',BKK:\'TH\',KUL:\'MY\',CGK:\'ID\',MNL:\'PH\',SGN:\'VN\',HAN:\'VN\',\n        DXB:\'AE\',AUH:\'AE\',DOH:\'QA\',JNB:\'ZA\',CPT:\'ZA\',GRU:\'BR\',GIG:\'BR\',EZE:\'AR\',SCL:\'CL\',MEX:\'MX\',\n        SHA:\'CN\',PVG:\'CN\',PEK:\'CN\',PKX:\'CN\',CAN:\'CN\',SZX:\'CN\',CTU:\'CN\',TFU:\'CN\',HGH:\'CN\',WUH:\'CN\',XIY:\'CN\'\n    };\n\n    const V45_CITY_COUNTRY = {\n        \'tokyo\':\'JP\',\'osaka\':\'JP\',\'nagoya\':\'JP\',\'fukuoka\':\'JP\',\'hong kong\':\'HK\',\'taipei\':\'TW\',\'kaohsiung\':\'TW\',\n        \'singapore\':\'SG\',\'seoul\':\'KR\',\'los angeles\':\'US\',\'san jose\':\'US\',\'san francisco\':\'US\',\'seattle\':\'US\',\n        \'frankfurt\':\'DE\',\'london\':\'GB\',\'paris\':\'FR\',\'amsterdam\':\'NL\',\'sydney\':\'AU\',\'melbourne\':\'AU\',\'toronto\':\'CA\',\n        \'vancouver\':\'CA\',\'mumbai\':\'IN\',\'delhi\':\'IN\',\'chennai\':\'IN\',\'bangalore\':\'IN\',\'bangkok\':\'TH\',\'kuala lumpur\':\'MY\',\n        \'jakarta\':\'ID\',\'manila\':\'PH\',\'ho chi minh city\':\'VN\',\'dubai\':\'AE\'\n    };\n\n    function v45CountryCode(rowOrDC, city) {\n        if (rowOrDC && typeof rowOrDC === \'object\') {\n            const explicit = String(rowOrDC.countryCode || rowOrDC.dcCountry || \'\').trim().toUpperCase();\n            if (/^[A-Z]{2}$/.test(explicit)) return explicit;\n            return v45CountryCode(rowOrDC.dc || rowOrDC.dataCenter || rowOrDC.DC || rowOrDC.DataCenter, rowOrDC.city || rowOrDC.City);\n        }\n        const dc = String(rowOrDC || \'\').trim().toUpperCase();\n        if (V45_DC_COUNTRY[dc]) return V45_DC_COUNTRY[dc];\n        const c = String(city || \'\').trim().toLowerCase();\n        if (V45_CITY_COUNTRY[c]) return V45_CITY_COUNTRY[c];\n        for (const [name, code] of Object.entries(V45_CITY_COUNTRY)) if (c.includes(name)) return code;\n        return \'-\';\n    }\n\n    function v45EnrichRow(row) {\n        const next = { ...(row || {}) };\n        next.countryCode = v45CountryCode(next);\n        return next;\n    }\n\n    function v45InstallExportCountryField() {\n        try {\n            if (Array.isArray(RESULT_FIELDS) && !RESULT_FIELDS.some(f => f.key === \'countryCode\')) {\n                const idx = RESULT_FIELDS.findIndex(f => f.key === \'region\');\n                RESULT_FIELDS.splice(idx >= 0 ? idx : RESULT_FIELDS.length, 0, { key: \'countryCode\', label: \'地区简称\' });\n            }\n        } catch (_) {}\n\n        if (typeof getCurrentResultRows === \'function\' && !getCurrentResultRows.__v45Wrapped) {\n            const original = getCurrentResultRows;\n            const wrapped = function(mode) {\n                const rows = original(mode) || [];\n                return rows.map(v45EnrichRow);\n            };\n            wrapped.__v45Wrapped = true;\n            getCurrentResultRows = wrapped;\n        }\n        try { if (typeof renderResultFieldOptions === \'function\') renderResultFieldOptions(); } catch (_) {}\n        try { if (typeof renderCopyFieldOptions === \'function\') renderCopyFieldOptions(); } catch (_) {}\n    }\n\n    function v45DecorateScanTable() {\n        v45DecorateQueued = false;\n        const table = document.getElementById(\'scanTable\');\n        const headerRow = table?.querySelector(\'thead tr\');\n        const tbody = table?.querySelector(\'tbody\');\n        if (!table || !headerRow || !tbody) return;\n\n        if (!headerRow.querySelector(\'.v45-seq-cell\')) {\n            const th = document.createElement(\'th\');\n            th.className = \'v45-seq-cell\';\n            th.textContent = \'#\';\n            headerRow.insertBefore(th, headerRow.firstElementChild);\n        }\n        let headers = Array.from(headerRow.children).map(th => th.textContent.trim());\n        let dcIndex = headers.findIndex(x => x === \'数据中心\');\n        if (dcIndex >= 0 && !headerRow.querySelector(\'.v45-country-cell\')) {\n            const th = document.createElement(\'th\');\n            th.className = \'v45-country-cell\';\n            th.textContent = \'地区简称\';\n            headerRow.insertBefore(th, headerRow.children[dcIndex + 1] || null);\n        }\n        headers = Array.from(headerRow.children).map(th => th.textContent.trim());\n        const countryIndex = headers.findIndex(x => x === \'地区简称\');\n        dcIndex = headers.findIndex(x => x === \'数据中心\');\n        const cityIndex = headers.findIndex(x => x === \'城市\');\n\n        Array.from(tbody.querySelectorAll(\'tr\')).forEach((tr, i) => {\n            let seq = tr.querySelector(\':scope > .v45-seq-cell\');\n            if (!seq) {\n                seq = document.createElement(\'td\');\n                seq.className = \'v45-seq-cell\';\n                tr.insertBefore(seq, tr.firstElementChild);\n            }\n            seq.textContent = String(i + 1);\n\n            if (countryIndex < 0 || dcIndex < 0) return;\n            let cc = tr.querySelector(\':scope > .v45-country-cell\');\n            if (!cc) {\n                cc = document.createElement(\'td\');\n                cc.className = \'v45-country-cell\';\n                tr.insertBefore(cc, tr.children[countryIndex] || null);\n            }\n            const cells = Array.from(tr.children);\n            const dc = cells[dcIndex]?.textContent?.trim() || \'\';\n            const city = cityIndex >= 0 ? (cells[cityIndex]?.textContent?.trim() || \'\') : \'\';\n            cc.textContent = v45CountryCode(dc, city);\n        });\n    }\n\n    function v45QueueDecorate() {\n        if (v45DecorateQueued) return;\n        v45DecorateQueued = true;\n        requestAnimationFrame(v45DecorateScanTable);\n    }\n\n    function v45InstallTableObserver() {\n        const table = document.getElementById(\'scanTable\');\n        if (!table) return;\n        const observer = new MutationObserver(v45QueueDecorate);\n        observer.observe(table, { subtree: true, childList: true, characterData: false });\n        v45QueueDecorate();\n    }\n\n    function v45ParseSpeed(value) {\n        const m = String(value ?? \'\').match(/(-?\\d+(?:\\.\\d+)?)\\s*MB\\/s/i);\n        return m ? parseFloat(m[1]) : 0;\n    }\n    function v45ParseLatency(value) {\n        const m = String(value ?? \'\').match(/(-?\\d+(?:\\.\\d+)?)\\s*ms/i);\n        return m ? parseFloat(m[1]) : Number.POSITIVE_INFINITY;\n    }\n    function v45ParseLoss(value) {\n        const m = String(value ?? \'\').match(/(-?\\d+(?:\\.\\d+)?)\\s*%/);\n        return m ? parseFloat(m[1]) : Number.POSITIVE_INFINITY;\n    }\n\n    function v45EndpointKey(row) {\n        const ip = String(row?.ip || row?.IP || \'\').trim().replace(/^\\[|\\]$/g, \'\').toLowerCase();\n        const port = String(row?.port || row?.Port || \'\').trim();\n        return `${ip}|${port}`;\n    }\n\n    function v45RowEndpoint(row) {\n        const ip = String(row?.ip || row?.IP || \'\').trim().replace(/^\\[|\\]$/g, \'\');\n        const port = String(row?.port || row?.Port || \'\').trim();\n        const host = ip.includes(\':\') ? `[${ip}]` : ip;\n        return port ? `${host}:${port}` : host;\n    }\n\n    function v45HistoryRows(rows) {\n        return (rows || []).map(v45EnrichRow).map(row => ({\n            ip: row.ip || row.IP || \'\', port: row.port || row.Port || \'\', dc: row.dc || row.dataCenter || row.DC || \'\',\n            countryCode: row.countryCode || v45CountryCode(row), latency: row.latency || row.Latency || \'-\',\n            lossRate: row.lossRate || row.LossRate || \'-\', speed: row.speed || row.Speed || \'-\',\n            ipType: row.ipType || row.IPType || \'\'\n        })).sort((a,b) => {\n            const sa=v45ParseSpeed(a.speed), sb=v45ParseSpeed(b.speed);\n            if (sa !== sb) return sb-sa;\n            const la=v45ParseLatency(a.latency), lb=v45ParseLatency(b.latency);\n            if (la !== lb) return la-lb;\n            return v45ParseLoss(a.lossRate)-v45ParseLoss(b.lossRate);\n        }).slice(0, 60);\n    }\n\n    function v45HashRows(rows, mode) {\n        let hash = 2166136261 >>> 0;\n        const keys = (rows || []).map(v45EndpointKey).sort();\n        const text = `${mode}|${keys.length}|${keys.join(\';\')}`;\n        for (let i=0;i<text.length;i++) { hash ^= text.charCodeAt(i); hash = Math.imul(hash, 16777619) >>> 0; }\n        return `${mode}-${hash.toString(16)}-${keys.length}`;\n    }\n\n    function v45HistorySource(mode) {\n        if (mode !== \'nsb\') return \'官方优选\';\n        const manual = document.getElementById(\'nsbManualInput\')?.value?.trim() || \'\';\n        if (manual) {\n            const count = manual.split(/[\\r\\n]+/).map(x=>x.trim()).filter(Boolean).length;\n            const first = manual.split(/[\\r\\n]+/).map(x=>x.trim()).filter(Boolean)[0] || \'\';\n            return `手动输入 ${count} 条${first ? ` · ${first}` : \'\'}`;\n        }\n        const url = document.getElementById(\'nsbSourceUrl\')?.value?.trim() || \'\';\n        if (url) return `URL · ${url}`;\n        try { if (typeof uploadedFileName !== \'undefined\' && uploadedFileName) return `文件 · ${uploadedFileName}`; } catch (_) {}\n        return \'非标输入\';\n    }\n\n    function v45LoadHistory() {\n        return [];\n    }\n    function v45SaveHistory(_) {\n        try { localStorage.removeItem(HISTORY_KEY); } catch (_) {}\n        v45UpdateHistoryBadge();\n    }\n    function v45LoadBest() {\n        try {\n            const v = JSON.parse(localStorage.getItem(BEST_KEY) || \'[]\');\n            return Array.isArray(v) ? v : [];\n        } catch (_) { return []; }\n    }\n    function v45SaveBest(items) {\n        const settings = v45LoadSettings();\n        const limit = Math.min(500, Math.max(1, parseInt(settings.historyLimit, 10) || 50));\n        const threshold = Math.max(0, Number(settings.bestSpeedThreshold) || 0);\n        const normalized = (Array.isArray(items) ? items : [])\n            .filter(x => x && x.key && Number(x.speed) > threshold)\n            .sort(v45BestCompare)\n            .slice(0, limit);\n        try { localStorage.setItem(BEST_KEY, JSON.stringify(normalized)); } catch (e) { console.warn(\'best save failed\', e); }\n        v45UpdateHistoryBadge();\n    }\n\n    function v45CurrentRows(mode) {\n        try {\n            if (mode === \'nsb\' && typeof getNSBResultObjects === \'function\') return (getNSBResultObjects() || []).map(v45EnrichRow);\n            if (typeof getCurrentResultRows === \'function\') return (getCurrentResultRows(mode === \'official\' ? \'test\' : mode) || []).map(v45EnrichRow);\n        } catch (e) { console.warn(\'v46 rows\', e); }\n        return [];\n    }\n\n    function v45UpdateHistoryBadge() {\n        const badge = document.getElementById(\'v45HistoryCount\');\n        if (badge) badge.textContent = String(v45LoadBest().length);\n    }\n\n    function v45InstallHistoryUI() {\n        try { localStorage.removeItem(HISTORY_KEY); } catch (_) {}\n\n        const top = document.querySelector(\'.top-actions\');\n        if (top && !document.getElementById(\'v45HistoryButton\')) {\n            const btn = document.createElement(\'button\');\n            btn.type = \'button\';\n            btn.id = \'v45HistoryButton\';\n            btn.className = \'settings-toggle v45-history-btn\';\n            btn.title = \'查看历史最优 IP\';\n            btn.innerHTML = `🏆 历史最优 <span id="v45HistoryCount" class="v45-history-count">0</span>`;\n            btn.addEventListener(\'click\', v45OpenHistory);\n            top.insertBefore(btn, top.firstChild);\n        }\n        if (!document.getElementById(\'v45HistoryOverlay\')) {\n            const overlay = document.createElement(\'div\');\n            overlay.id = \'v45HistoryOverlay\';\n            overlay.className = \'v45-overlay hidden\';\n            overlay.innerHTML = `<div class="v45-history-panel" role="dialog" aria-modal="true">\n                <div class="v45-history-head"><div><h3>🏆 历史最优</h3><div class="v45-history-meta" id="v45HistorySub"></div></div>\n                <div class="v45-history-actions"><button type="button" id="v45ClearBest">清空历史最优</button><button type="button" id="v45CloseHistory">关闭</button></div></div>\n                <div class="v45-history-body" id="v45HistoryBody"></div>\n            </div>`;\n            document.body.appendChild(overlay);\n            overlay.addEventListener(\'click\', e => { if (e.target === overlay) v45CloseHistory(); });\n            document.getElementById(\'v45CloseHistory\')?.addEventListener(\'click\', v45CloseHistory);\n            document.getElementById(\'v45ClearBest\')?.addEventListener(\'click\', () => {\n                if (!confirm(\'确定清空历史最优池？不会自动删除 GitHub best.txt。\')) return;\n                localStorage.removeItem(BEST_KEY);\n                v45UpdateHistoryBadge();\n                v45RenderHistory();\n            });\n        }\n        v45UpdateHistoryBadge();\n    }\n\n    function v45OpenHistory() {\n        document.getElementById(\'v45HistoryOverlay\')?.classList.remove(\'hidden\');\n        v45RenderHistory();\n    }\n    function v45CloseHistory() { document.getElementById(\'v45HistoryOverlay\')?.classList.add(\'hidden\'); }\n    window.openCFDataHistory = v45OpenHistory;\n\n    function v45RenderHistory() {\n        const body = document.getElementById(\'v45HistoryBody\');\n        if (!body) return;\n        const settings = v45LoadSettings();\n        const threshold = Math.max(0, Number(settings.bestSpeedThreshold) || 0);\n        const limit = Math.min(500, Math.max(1, parseInt(settings.historyLimit,10) || 50));\n        const best = v45LoadBest().filter(x => Number(x.speed) > threshold).sort(v45BestCompare).slice(0, limit);\n        const sub = document.getElementById(\'v45HistorySub\');\n        if (sub) sub.textContent = `只保留速度 > ${threshold} MB/s 的历史 Top ${limit} · 当前 ${best.length}/${limit}`;\n        if (!best.length) {\n            body.innerHTML = `<div class="v45-history-empty">暂无历史最优。只有速度超过 ${v45EscapeHTML(threshold)} MB/s 的 IP 才会进入这里。</div>`;\n            return;\n        }\n        const rows = best.map((entry, i) => {\n            const r = entry.row || {};\n            const endpoint = r.ip ? v45RowEndpoint(r) : ((entry.line || \'\').split(\'#\')[0] || entry.key || \'-\');\n            const updated = entry.updatedAt ? new Date(entry.updatedAt).toLocaleString() : \'-\';\n            return `<tr><td>${i+1}</td><td>${v45EscapeHTML(endpoint)}</td><td>${v45EscapeHTML(r.countryCode||\'-\')}</td><td>${v45EscapeHTML(r.dc||\'-\')}</td><td>${v45EscapeHTML(Number.isFinite(Number(entry.latency)) ? `${entry.latency}ms` : (r.latency||\'-\'))}</td><td>${v45EscapeHTML(Number.isFinite(Number(entry.loss)) ? `${entry.loss}%` : (r.lossRate||\'-\'))}</td><td><strong>${v45EscapeHTML(Number(entry.speed).toFixed(2))} MB/s</strong></td><td>${v45EscapeHTML(updated)}</td></tr>`;\n        }).join(\'\');\n        body.innerHTML = `<div class="v45-history-table-wrap"><table class="v45-history-table"><thead><tr><th>#</th><th>IP:PORT</th><th>地区</th><th>DC</th><th>延迟</th><th>丢包</th><th>速度</th><th>更新时间</th></tr></thead><tbody>${rows}</tbody></table></div>`;\n    }\n\n    function v45BestCompare(a,b) {\n        const sa=Number(a.speed)||0, sb=Number(b.speed)||0;\n        if (sa !== sb) return sb-sa;\n        const la=Number.isFinite(Number(a.latency))?Number(a.latency):Infinity;\n        const lb=Number.isFinite(Number(b.latency))?Number(b.latency):Infinity;\n        if (la !== lb) return la-lb;\n        const pa=Number.isFinite(Number(a.loss))?Number(a.loss):Infinity;\n        const pb=Number.isFinite(Number(b.loss))?Number(b.loss):Infinity;\n        return pa-pb;\n    }\n\n    function v46MergeBestEntries(existing, incoming, threshold, limit) {\n        const map = new Map();\n        const add = (entry) => {\n            if (!entry || !entry.key || !(Number(entry.speed) > threshold)) return;\n            const old = map.get(entry.key);\n            if (!old || v45BestCompare(entry, old) < 0) map.set(entry.key, entry);\n        };\n        (existing || []).forEach(add);\n        (incoming || []).forEach(add);\n        return Array.from(map.values()).sort(v45BestCompare).slice(0, limit);\n    }\n\n    function v45BestEntryFromRow(row) {\n        const enriched = v45EnrichRow(row);\n        return {\n            key: v45EndpointKey(enriched),\n            speed: v45ParseSpeed(enriched.speed || enriched.Speed),\n            latency: v45ParseLatency(enriched.latency || enriched.Latency),\n            loss: v45ParseLoss(enriched.lossRate || enriched.LossRate),\n            row: enriched,\n            updatedAt: new Date().toISOString()\n        };\n    }\n\n    function v45ParseRemoteLine(line) {\n        const raw = String(line || \'\').trim();\n        if (!raw) return null;\n        const first = raw.split(\'#\')[0].trim();\n        let ip=\'\', port=\'\';\n        let m = first.match(/^\\[([^\\]]+)\\]:(\\d+)$/);\n        if (m) { ip=m[1]; port=m[2]; }\n        else {\n            m = first.match(/^(\\d{1,3}(?:\\.\\d{1,3}){3}):(\\d+)$/);\n            if (m) { ip=m[1]; port=m[2]; }\n            else return null;\n        }\n        return {\n            key: `${ip.toLowerCase()}|${port}`,\n            speed: v45ParseSpeed(raw), latency: v45ParseLatency(raw), loss: v45ParseLoss(raw),\n            line: raw, row: null, updatedAt: \'\'\n        };\n    }\n\n    function v45BestLine(entry) {\n        if (entry?.row) {\n            try {\n                const fields = typeof getDefaultResultFieldOrderFor === \'function\' ? getDefaultResultFieldOrderFor(\'nsb\',\'txt\') : [];\n                if (typeof buildResultContent === \'function\' && fields.length) return buildResultContent(\'txt\', [v45EnrichRow(entry.row)], fields, \'-\').trim();\n            } catch (_) {}\n        }\n        return String(entry?.line || \'\').trim();\n    }\n\n    function v45BestPath(basePath) {\n        const p = String(basePath || \'\').trim().replace(/^\\/+|\\/+$/g,\'\');\n        if (!p) return \'best.txt\';\n        if (p.endsWith(\'/\')) return `${p}best.txt`;\n        const parts = p.split(\'/\');\n        if (parts.length <= 1) return \'best.txt\';\n        parts.pop();\n        return `${parts.join(\'/\')}/best.txt`;\n    }\n\n    async function v45ResolveGitHubConfig() {\n        let repoText = document.getElementById(\'githubRepo\')?.value?.trim() || \'\';\n        let branch = document.getElementById(\'githubBranch\')?.value?.trim() || \'main\';\n        let basePath = document.getElementById(\'githubPath\')?.value?.trim() || \'\';\n        let token = document.getElementById(\'githubToken\')?.value?.trim() || \'\';\n        let account = null;\n        let idx = NaN;\n\n        try {\n            const autoValue = document.getElementById(\'nsbAutoUploadAccount\')?.value || \'\';\n            if (autoValue) idx = parseInt(autoValue.split(\':\')[0], 10);\n            if (!Number.isFinite(idx)) idx = parseInt(document.getElementById(\'githubAccountSelect\')?.value || \'\', 10);\n            const accounts = typeof getGitHubAccounts === \'function\' ? getGitHubAccounts() : [];\n            if (!Number.isFinite(idx) && accounts.length === 1) idx = 0;\n            if (Number.isFinite(idx)) account = accounts[idx] || null;\n            if (account) {\n                if (!repoText) repoText = account.repo || \'\';\n                if (!basePath) basePath = account.path || \'\';\n                if (!branch || branch === \'main\') branch = account.branch || branch || \'main\';\n                const key = typeof normalizeGitHubAccountKey === \'function\' ? normalizeGitHubAccountKey(account) : (account.name || account.repo || \'\');\n                if (!token && typeof githubSessionTokens !== \'undefined\') token = githubSessionTokens.get(key) || \'\';\n                if (!token && account.token && typeof migrateLegacyGitHubToken === \'function\') token = await migrateLegacyGitHubToken(account, idx);\n                if (!token && account.tokenCipher && typeof decryptStoredGitHubToken === \'function\') token = await decryptStoredGitHubToken(account);\n                if (token && typeof githubSessionTokens !== \'undefined\' && key) githubSessionTokens.set(key, token);\n            }\n        } catch (e) { console.warn(\'resolve github\', e); }\n\n        const parts = repoText.split(\'/\');\n        if (!token || parts.length !== 2 || !parts[0] || !parts[1]) return null;\n        return { token, owner: parts[0], repo: parts[1], branch: branch || \'main\', path: v45BestPath(basePath) };\n    }\n\n    async function v45FetchRemoteBest(cfg) {\n        const path = cfg.path.split(\'/\').map(encodeURIComponent).join(\'/\');\n        const branch = cfg.branch.split(\'/\').map(encodeURIComponent).join(\'/\');\n        const url = `https://raw.githubusercontent.com/${encodeURIComponent(cfg.owner)}/${encodeURIComponent(cfg.repo)}/${branch}/${path}?t=${Date.now()}`;\n        const resp = await fetch(url, { cache:\'no-store\' });\n        if (resp.status === 404) return [];\n        if (!resp.ok) throw new Error(`读取远端 best.txt 失败: HTTP ${resp.status}`);\n        const text = await resp.text();\n        return text.split(/\\r?\\n/).map(v45ParseRemoteLine).filter(Boolean);\n    }\n\n    async function v45UpdateBestAndSync(rows) {\n        const settings = v45LoadSettings();\n        const threshold = Math.max(0, Number(settings.bestSpeedThreshold) || 0);\n        const limit = Math.min(500, Math.max(1, parseInt(settings.historyLimit,10) || 50));\n        const candidates = (rows || []).map(v45BestEntryFromRow).filter(x => x.key && x.speed > threshold);\n\n        const local = v46MergeBestEntries(v45LoadBest(), candidates, threshold, limit);\n        v45SaveBest(local);\n        v45RenderHistory();\n\n        if (!candidates.length) return;\n\n        const signature = local.map(x=>`${x.key}:${Number(x.speed).toFixed(2)}:${Number(x.latency)||0}:${Number(x.loss)||0}`).join(\'|\');\n        if (signature && signature === v45LastBestSyncSignature) return;\n\n        const cfg = await v45ResolveGitHubConfig();\n        if (!cfg) {\n            if (typeof log === \'function\') log(`历史最优：本次 ${candidates.length} 条速度 > ${threshold}MB/s；当前 Top ${limit} 共 ${local.length} 条，未配置可用 GitHub Token`);\n            return;\n        }\n\n        let remote = [];\n        try {\n            remote = await v45FetchRemoteBest(cfg);\n        } catch (e) {\n            if (typeof log === \'function\') log(`best.txt 自动入库跳过：${e.message || e}`);\n            return;\n        }\n\n        const merged = v46MergeBestEntries(remote, local, threshold, limit);\n        const content = merged.map(v45BestLine).filter(Boolean).join(\'\\n\') + (merged.length ? \'\\n\' : \'\');\n        if (!content) return;\n\n        v45SaveBest(merged.map(x => x.row ? x : { ...x, line: v45BestLine(x) }));\n        v45LastBestSyncSignature = signature;\n\n        if (typeof sendGitHubUpload === \'function\') {\n            sendGitHubUpload({\n                token:cfg.token, owner:cfg.owner, repo:cfg.repo, branch:cfg.branch,\n                path:cfg.path, message:\'update cfdata historical best\', content, silent:true\n            });\n            if (typeof log === \'function\') log(`best.txt 历史最优已更新：速度 > ${threshold}MB/s，最终 Top ${limit} 保留 ${merged.length} 条；排序=速度↓ 延迟↑ 丢包↑`);\n        }\n    }\n\n    async function v45AfterNSBComplete() {\n        const rows = v45CurrentRows(\'nsb\');\n        if (rows?.length) await v45UpdateBestAndSync(rows);\n    }\n\n    function v45AfterOfficialComplete() {\n        const rows = v45CurrentRows(\'official\');\n        if (!rows?.length) return;\n        const settings = v45LoadSettings();\n        const threshold = Math.max(0, Number(settings.bestSpeedThreshold) || 0);\n        const limit = Math.min(500, Math.max(1, parseInt(settings.historyLimit,10) || 50));\n        const candidates = rows.map(v45BestEntryFromRow).filter(x => x.key && x.speed > threshold);\n        v45SaveBest(v46MergeBestEntries(v45LoadBest(), candidates, threshold, limit));\n        v45RenderHistory();\n    }\n\n    function v45WrapCompletionHooks() {\n        if (typeof autoUploadNSBResults === \'function\' && !autoUploadNSBResults.__v45Wrapped) {\n            v45OriginalAutoUploadNSB = autoUploadNSBResults;\n            const wrapped = async function(...args) {\n                try { await v45AfterNSBComplete(); } catch (e) { console.warn(\'v46 NSB historical-best\', e); }\n                return await v45OriginalAutoUploadNSB.apply(this, args);\n            };\n            wrapped.__v45Wrapped = true;\n            autoUploadNSBResults = wrapped;\n        }\n        if (typeof autoUploadOfficialResults === \'function\' && !autoUploadOfficialResults.__v45Wrapped) {\n            v45OriginalAutoUploadOfficial = autoUploadOfficialResults;\n            const wrapped = async function(...args) {\n                try { v45AfterOfficialComplete(); } catch (e) { console.warn(\'v46 official historical-best\', e); }\n                return await v45OriginalAutoUploadOfficial.apply(this, args);\n            };\n            wrapped.__v45Wrapped = true;\n            autoUploadOfficialResults = wrapped;\n        }\n    }\n\n    function v45Init() {\n        v45InstallCompactSettings();\n        v45InstallIPRendering();\n        v45InstallExportCountryField();\n        v45InstallHistoryUI();\n        v45InstallTableObserver();\n        v45WrapCompletionHooks();\n        v45DecorateScanTable();\n    }\n\n    if (document.readyState === \'loading\') document.addEventListener(\'DOMContentLoaded\', v45Init, { once:true });\n    else setTimeout(v45Init, 0);\n})();\n'

